import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as r}from"./app-C34p0aR5.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S09/S09E20.html","title":"S09E20 The One with the Soap Opera Party","lang":"zh-CN","frontmatter":{"title":"S09E20 The One with the Soap Opera Party","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":214},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":33.59,"words":10078},"filePathRelative":"语言/英语/Friends老友记/S09/S09E20.md"}`),a={name:`S09E20.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-the-soap-opera-party" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-soap-opera-party"><span>The One with the Soap Opera Party</span></a></h1><blockquote><p><em>肥皂剧派对</em></p></blockquote><p><strong>Teleplay:</strong> Andrew Reich &amp; Ted Cohen</p><blockquote><p>安德鲁·里奇和特德·科恩</p></blockquote><p><strong>Story:</strong> Shana Goldberg-Meehan</p><blockquote><p>莎娜·戈德伯格·米汉</p></blockquote><p><strong>Directed by: Sheldon Epps</strong></p><blockquote><p>导演：Sheldon Epps</p></blockquote><p><strong>Transcribed by: Eleonora, Pheeboh, Sebastiano &amp; Vanessa</strong></p><blockquote><p>转录人：Eleonora、Pheeboh、Sebastiano&amp;Vanessa</p></blockquote><hr><p>🎬 <em>Monica&#39;s apartment</em></p><blockquote><p>🎬 <em>莫妮卡的公寓</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (enters the room) Hey, you guys, what are you doing tomorrow night?</p><blockquote><p>（走进房间）嘿，你们这些家伙，明晚你们要干什么？</p></blockquote><p><strong>Chandler Bing:</strong> (browsing through a diary) Well, let me see... I-I believe I&#39;m... yes, falling asleep in front of the TV.</p><blockquote><p>（浏览日记）好吧，让我想想。。。我相信我。。。是的，在电视机前睡着了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Look, my agent hooked me up with six tickets to a great play.</p><blockquote><p>听着，我的经纪人给我弄到了六张精彩戏剧的票。</p></blockquote><p><strong>Chandler Bing:</strong> I could fall asleep at a play.</p><blockquote><p>我可以在看戏的时候睡着。</p></blockquote><p><strong>Phoebe Buffay:</strong> What is it?</p><blockquote><p>什么事？</p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s a one-woman play called &quot;Why don&#39;t you like me: a bitter woman&#39;s journey through life&quot;.</p><blockquote><p>这是一部名为《你为什么不喜欢我：一个苦涩女人的人生旅程》的独角戏。</p></blockquote><p><strong>Monica Geller:</strong> It sounds interesting!</p><blockquote><p>听起来很有趣！</p></blockquote><p><strong>Ross Geller:</strong> Yeah, it does sound interesting, I mean, to listen to a woman complain for two hours, I don&#39;t think it gets bett... (Ross starts snoring, faking to fall asleep)</p><blockquote><p>是啊，听起来确实很有趣，我的意思是，听一个女人抱怨两个小时，我不认为这会更好。。。（罗斯开始打鼾，假装睡着了）</p></blockquote><p><strong>Phoebe Buffay:</strong> I know, I know, we can drive, we can vote, we can work, what more do these broads want?</p><blockquote><p>我知道，我知道，我们可以开车，我们可以投票，我们可以工作，这些女人还想要什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> You guys are gonna have a great time, I promise!</p><blockquote><p>你们会玩得很开心的，我保证！</p></blockquote><p><strong>Ross Geller:</strong> What? How come that you don&#39;t have to go!</p><blockquote><p>什么？为什么你不必去呢！</p></blockquote><p><strong>Joey Tribbiani:</strong> I wish I could but I just found out that I have to be at work really early the next day, so I can&#39;t go, but, you know, take the extra ticket and invite whoever you want.</p><blockquote><p>我希望我能去，但我刚发现第二天我得很早上班，所以我不能去，但是，你知道，拿着多余的票，邀请任何你想邀请的人。</p></blockquote><p><strong>Chandler Bing:</strong> (browsing through a diary) Uh, let&#39;s see, who do I hate?</p><blockquote><p>（浏览日记）嗯，让我想想，我恨谁？</p></blockquote><p><strong>Rachel Green:</strong> (gets up from the sofa and moves to the kitchen but Joey blocks her way) Oh, sorry... Oops, sorry.</p><blockquote><p>（从沙发上站起来，走向厨房，但乔伊挡住了她的路）哦，对不起。。。哦，对不起。</p></blockquote><p><strong>Joey Tribbiani:</strong> (lifts Rachel up and moves her behind him so she can walk on) Hey, here you go.</p><blockquote><p>（抬起瑞秋，把她移到他身后，这样她就可以继续走了）嘿，给你。</p></blockquote><p><strong>Rachel Green:</strong> Ooh... oooh... (pause) (Rachel is all bah-jiggity about Joey) oh, ah... (pause) (to Monica) Can I ask you a question?</p><blockquote><p>哦。。。哦。。。（停顿）（瑞秋对乔伊非常好奇）哦，啊。。。（停顿）（对莫妮卡）我能问你一个问题吗？</p></blockquote><p><strong>Monica Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Rachel Green:</strong> Do you think it&#39;s possible for two friends to fool around and... and not have it be a big deal?</p><blockquote><p>你觉得两个朋友有可能鬼混然后。。。这不是什么大不了的事吗？</p></blockquote><p><strong>Monica Geller:</strong> No, I don&#39;t think it ever works. Why?</p><blockquote><p>不，我认为它永远不会起作用。为什么？</p></blockquote><p><strong>Rachel Green:</strong> No reason.</p><blockquote><p>没有理由。</p></blockquote><p><strong>Monica Geller:</strong> No, no, Rachel?</p><blockquote><p>不，不，瑞秋？</p></blockquote><p><strong>Rachel Green:</strong> Yeah</p><blockquote><p>是的</p></blockquote><p><strong>Monica Geller:</strong> Who do you wanna fool around with?</p><blockquote><p>你想和谁鬼混？</p></blockquote><p><strong>Rachel Green:</strong> (with high pitched voice) Nobody, forget it!</p><blockquote><p>（高声）没人，算了吧！</p></blockquote><p><em>(Monica points at Joey, Rachel turns and sees him)</em></p><blockquote><p><em>（莫妮卡指着乔伊，瑞秋转身看见了他）</em></p></blockquote><p><strong>Rachel Green:</strong> (giggling and whispering) Maybe.</p><blockquote><p>（咯咯笑着低声说）也许吧。</p></blockquote><p><strong>Monica Geller:</strong> (whispering) You can&#39;t!</p><blockquote><p>（耳语）你不能！</p></blockquote><p><strong>Rachel Green:</strong> (whispering) Why? (Monica gesticulates mumbling something that starts with &quot;because&quot;) Seriously I did not understand a word that you said.</p><blockquote><p>（耳语）为什么？（莫妮卡做手势，咕哝着以“因为”开头的话）说真的，你说的我一个字都听不懂。</p></blockquote><p><strong>Monica Geller:</strong> In the hall.</p><blockquote><p>在大厅里。</p></blockquote><hr><p>🎬 <em>In the hall</em></p><blockquote><p>🎬 <em>大厅里</em></p></blockquote><p><strong>Monica Geller:</strong> You wanna fool around with Joey?</p><blockquote><p>你想和乔伊鬼混吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah! You know, ever since I had that dream about him, and can&#39;t get it out of my head! And what&#39;s the big deal, people do it all the time!</p><blockquote><p>是啊！你知道吗，自从我做了那个关于他的梦，我就想不起来了！有什么大不了的，人们总是这么做！</p></blockquote><p><strong>Monica Geller:</strong> Who? Who do you know that are friends that just fool around?</p><blockquote><p>谁？你知道谁是只会胡闹的朋友吗？</p></blockquote><p><strong>Rachel Green:</strong> Ok, off the top of my head... Don and Janet.</p><blockquote><p>好吧，从我的头顶上。。。唐和珍妮特。</p></blockquote><p><strong>Monica Geller:</strong> Who, who are they?</p><blockquote><p>谁，他们是谁？</p></blockquote><p><strong>Rachel Green:</strong> I know them from work.</p><blockquote><p>我从工作中认识他们。</p></blockquote><p><strong>Monica Geller:</strong> Both of them?</p><blockquote><p>都是吗？</p></blockquote><p><strong>Rachel Green:</strong> No, one of them...</p><blockquote><p>不，其中一个。。。</p></blockquote><p><strong>Monica Geller:</strong> Which one?</p><blockquote><p>哪一个？</p></blockquote><p><strong>Rachel Green:</strong> I don&#39;t know, what were the names I just said?</p><blockquote><p>我不知道，我刚才说的是什么名字？</p></blockquote><p><strong>Monica Geller:</strong> Rachel, things can get incredibly complicated.</p><blockquote><p>瑞秋，事情会变得非常复杂。</p></blockquote><p><strong>Rachel Green:</strong> All right, all right, you&#39;re right, I won&#39;t do anything with Joey, I just thought that we (Joey enters the hall) Ok so that would be two cups of tarragon, one pound of baking soda and one red onion? (Joey enters his apartment)</p><blockquote><p>好吧，好吧，你说得对，我不会和乔伊做任何事，我只是想我们（乔伊进入大厅）好吧，那就是两杯龙蒿，一磅小苏打和一个红洋葱？（乔伊走进他的公寓）</p></blockquote><p><strong>Monica Geller:</strong> What the hell are you cooking!</p><blockquote><p>你到底在做什么呀！</p></blockquote><p>Opening credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, Ross enters</em></p><blockquote><p>🎬 <em>中央公园，罗斯进来</em></p></blockquote><p><strong>Ross Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Chandler Bing:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Ross Geller:</strong> Hey, you guys won&#39;t believe what I have to do for work today.</p><blockquote><p>嘿，你们不会相信我今天的工作。</p></blockquote><p><strong>Chandler Bing:</strong> Yes, but, Ross you chose a career of talking about dinosaurs.</p><blockquote><p>是的，但是，罗斯，你选择了谈论恐龙的职业。</p></blockquote><p><strong>Ross Geller:</strong> (covering with his hand Chandler&#39;s face, like pretending he&#39;s not there) (to Monica) There&#39;re these two professors who are joining my department and I have to meet them here and show them around campus.</p><blockquote><p>（用手捂住钱德勒的脸，假装他不在那里）（对莫妮卡）有两位教授要加入我的系，我必须在这里见他们，带他们参观校园。</p></blockquote><p><strong>Monica Geller:</strong> What&#39;s so bad about that?</p><blockquote><p>那有什么不好？</p></blockquote><p><strong>Ross Geller:</strong> It&#39;s I just know they&#39;re gonna be a couple of windbags wearing tweed jackets with suede elbow patches.</p><blockquote><p>我只知道会有两个风包，穿着粗花呢夹克和翻毛皮肘部补丁。</p></blockquote><p><strong>Monica Geller:</strong> (fingering her elbow): Ross?</p><blockquote><p>（抚摸她的胳膊肘）：罗斯？</p></blockquote><p><strong>Ross Geller:</strong> (looking his elbow, where there&#39;s a patch) These aren&#39;t suede.</p><blockquote><p>（看他的肘部，有补丁的地方）这不是绒面革。</p></blockquote><p><em>(a woman walks in)</em></p><blockquote><p><em>（一个女人走进来）</em></p></blockquote><p><strong>Charlie:</strong> (to Gunther) Excuse me, I&#39;m looking for someone. You don&#39;t, by any chance, know a Ross Geller?</p><blockquote><p>（对冈瑟）对不起，我在找人。你不认识罗斯·盖勒吗？</p></blockquote><p><strong>Gunther:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Ross Geller:</strong> Hi, hi, I&#39;m Ross Geller.</p><blockquote><p>嗨，嗨，我是罗斯·盖勒。</p></blockquote><p><strong>Charlie:</strong> Oh, hi. I&#39;m professor Wealer.</p><blockquote><p>哦，嗨。我是韦勒教授。</p></blockquote><p><strong>Ross Geller:</strong> Oh, oh, that&#39;s, that&#39;s, that&#39;s nice.</p><blockquote><p>哦，哦，那，那，那很好。</p></blockquote><p><strong>Charlie:</strong> It&#39;s a... It&#39;s good to meet you! Thank you so much for taking the time out to show me around.</p><blockquote><p>这是。。。很高兴认识你！非常感谢你抽出时间带我四处看看。</p></blockquote><p><strong>Ross Geller:</strong> Oh, no, it&#39;s no big deal, I mean, if I weren&#39;t doing this I&#39;d just, you know, be at the gym working out.</p><blockquote><p>哦，不，没什么大不了的，我是说，如果我不这么做的话，我只会，你知道，在健身房锻炼。</p></blockquote><p><strong>Monica Geller:</strong> (to Chandler) Is he gonna introduce us?</p><blockquote><p>（对钱德勒）他会介绍我们吗？</p></blockquote><p><strong>Chandler Bing:</strong> (to Monica) No, I think we&#39;re just blurry shapes to him now.</p><blockquote><p>（对莫妮卡）不，我想我们现在对他来说只是模糊的形状。</p></blockquote><p><strong>Charlie:</strong> And, by the way, I really enjoyed your paper on the connection between geographic isolation and rapid mutagenesis.</p><blockquote><p>顺便说一句，我很喜欢你关于地理隔离和快速突变之间关系的论文。</p></blockquote><p><strong>Ross Geller:</strong> Oh, ha, I wrote that in one minute.</p><blockquote><p>哦，哈，我一分钟就写了。</p></blockquote><p><strong>Monica Geller:</strong> (to chandler) Twenty bucks says they&#39;re married within the month.</p><blockquote><p>（对钱德勒）二十块钱说他们一个月内就结婚了。</p></blockquote><p><strong>Ross Geller:</strong> (hitting Monica with his suitcase) (to Charlie) We should probably get going, you know, we got a lot of ground to cover.</p><blockquote><p>（用手提箱打莫妮卡）（对查理）我们应该走了，你知道，我们有很多地方要覆盖。</p></blockquote><p><strong>Charlie:</strong> Oh, ah, isn&#39;t there another professor that is supposed to come with us?</p><blockquote><p>哦，啊，难道没有另一位教授应该和我们一起去吗？</p></blockquote><p><strong>Ross Geller:</strong> I don&#39;t think so.</p><blockquote><p>我不这么认为。</p></blockquote><p><strong>Charlie:</strong> I&#39;m pretty sure, professor Spafford from Cornell?</p><blockquote><p>我很确定，康奈尔大学的斯帕福德教授？</p></blockquote><p><strong>Ross Geller:</strong> Oh, well he&#39;s obviously late and the rule in my class is &quot;if you can&#39;t come on time, then don&#39;t come at all&quot;. (pause) An option that many of my students use. (pause) Shall we?</p><blockquote><p>哦，他显然迟到了，我们班的规矩是“如果你不能准时来，那就别来”。（停顿）我的许多学生使用的选项。（停顿）好吗？</p></blockquote><p><strong>Charlie:</strong> You don&#39;t think we should wait for him?</p><blockquote><p>你不认为我们应该等他吗？</p></blockquote><p><strong>Ross Geller:</strong> You know what, he&#39;s a big boy, I&#39;m sure he&#39;ll find us, ok?</p><blockquote><p>你知道吗，他是个大男孩，我相信他会找到我们的，好吗？</p></blockquote><p><strong>Professor Spafford:</strong> Professor Geller?</p><blockquote><p>盖勒教授？</p></blockquote><p><strong>Ross Geller:</strong> Oh, damn it!</p><blockquote><p>哦，该死！</p></blockquote><hr><p>🎬 <em>Joey&#39;s apartment</em></p><blockquote><p>🎬 <em>乔伊的公寓</em></p></blockquote><p><em>(Rachel enters the room and checks the answering machine)</em></p><blockquote><p><em>（瑞秋走进房间，检查电话答录机）</em></p></blockquote><p><strong>Jane:</strong> (from the answering machine) Hi Joey it&#39;s Jane Rogers, can&#39;t wait for your party tonight. Listen, I forgot your address, can you give me a call? Thanks, bye.</p><blockquote><p>（通过电话答录机）嗨，乔伊，我是简·罗杰斯，等不及今晚的派对了。听着，我忘了你的地址，你能给我打个电话吗？谢谢，再见。</p></blockquote><p><strong>Joey Tribbiani:</strong> (entering the room) Hey!</p><blockquote><p>（走进房间）嘿！</p></blockquote><p><strong>Rachel Green:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> What&#39;s happenin&#39;?</p><blockquote><p>发生了什么事？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, it&#39;s a real shame you can&#39;t make it to that one-woman show tonight.</p><blockquote><p>是啊，你不能参加今晚的一个女人秀真是太遗憾了。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, I&#39;d love to, but I gotta get up so early the next day and so, you know me, work comes first</p><blockquote><p>哦，我很想去，但我第二天得起得这么早，所以，你知道我，工作是第一位的</p></blockquote><p><strong>Rachel Green:</strong> Oh, yeah, yeah, yeah... (she plays the answering machine)</p><blockquote><p>哦，是的，是的，是的。。。（她玩电话答录机）</p></blockquote><p><strong>Message:</strong> &quot;Hi Joey, it&#39;s Jane Rogers can&#39;t wait for your party tonight&quot; (Joey&#39;s upset and stops it)</p><blockquote><p>“嗨，乔伊，我是简·罗杰斯，等不及你今晚的聚会了”（乔伊心烦意乱，停了下来）</p></blockquote><p><strong>Joey Tribbiani:</strong> (yelling) Stupid Jane Rogers!!</p><blockquote><p>（大叫）愚蠢的简·罗杰斯！！</p></blockquote><p><strong>Rachel Green:</strong> (angry) You are having a party tonight??</p><blockquote><p>（生气）你今晚要开派对吗？？</p></blockquote><p><strong>Joey Tribbiani:</strong> Kinda have a... a thing for the Days Of Our Life&#39;s people.</p><blockquote><p>有点。。。这是我们生活中的人们的一件事。</p></blockquote><p><strong>Rachel Green:</strong> And you weren&#39;t going to tell us? How did you think you were gonna get away with that?</p><blockquote><p>你不打算告诉我们？你以为你怎么能逃脱惩罚？</p></blockquote><p><strong>Joey Tribbiani:</strong> I do it every year.</p><blockquote><p>我每年都这么做。</p></blockquote><p><strong>Rachel Green:</strong> You do that every year??</p><blockquote><p>你每年都这么做？？</p></blockquote><p><strong>Joey Tribbiani:</strong> I didn&#39;t have to tell you that!! I&#39;m stupider than Jane Rogers!!</p><blockquote><p>我没必要告诉你！！我比简·罗杰斯傻！！</p></blockquote><p><strong>Rachel Green:</strong> Oh, that&#39;s why you got these tickets to that play, to get rid of us??</p><blockquote><p>哦，这就是为什么你买了那场戏的票，为了摆脱我们？？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah...</p><blockquote><p>是的。。。</p></blockquote><p><strong>Rachel Green:</strong> And last year is that why you sent us to that medieval times restaurant?</p><blockquote><p>这就是去年你送我们去中世纪餐馆的原因吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah...</p><blockquote><p>是的。。。</p></blockquote><p><strong>Rachel Green:</strong> OH! And the year before that, when you set up that nighttime tour of that button factory?</p><blockquote><p>哦！而在那之前的一年，你什么时候开始了那家纽扣工厂的夜间巡演？</p></blockquote><p><strong>Joey Tribbiani:</strong> (Smiling) I can&#39;t believe you guys went for that one!</p><blockquote><p>（微笑）我真不敢相信你们会选那个！</p></blockquote><p><strong>Rachel Green:</strong> Joey, why wouldn&#39;t you invite us to your parties?</p><blockquote><p>乔伊，你为什么不邀请我们参加你的派对？</p></blockquote><p><strong>Joey Tribbiani:</strong> You&#39;re fine, ok? But everyone else acts like an idiot around famous people!</p><blockquote><p>你很好，好吗？但其他人在名人面前都像个白痴！</p></blockquote><p><strong>Rachel Green:</strong> Well, then so you just invite me...!</p><blockquote><p>好吧，那你就请我。。。！</p></blockquote><p><strong>Joey Tribbiani:</strong> (speaking aloud) Please, I was trying to be nice, you&#39;re the worst one!</p><blockquote><p>（大声说）拜托，我只是想表现得好一点，你是最坏的一个！</p></blockquote><p><strong>Rachel Green:</strong> Oh, Joey, come on! Please, please! Let me come, I will behave, I promise! I will behave! Please, please, please...</p><blockquote><p>哦，乔伊，来吧！求你了，求你了！让我来，我保证，我会守规矩的！我会守规矩的！求你了，求你了，求你了。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ok, ok! Fine! You can come, but don&#39;t tell anybody else. It&#39;s up on the roof at 8.</p><blockquote><p>好的，好的！好的你可以来，但不要告诉别人。8点在屋顶上。</p></blockquote><p><strong>Rachel Green:</strong> (yelling and jumping like a child) OH, a soap opera roof party!! I&#39;m going to a soap opera roof party!! Oh my God, oh my God!! (realizing how she&#39;s behaving) And it&#39;s out of my system!</p><blockquote><p>（像孩子一样大喊大叫，蹦蹦跳跳）哦，肥皂剧屋顶派对！！我要去一个肥皂剧屋顶派对！！我的天啊，我的天啊！！（意识到她的行为）这超出了我的系统！</p></blockquote><hr><p>🎬 <em>Ross, Charlie and Professor Spafford are sitting at the table in a restaurant</em></p><blockquote><p>🎬 <em>罗斯、查理和斯帕福德教授坐在餐厅的桌子旁</em></p></blockquote><p><strong>Professor Spafford:</strong> (speaking very slowly) And then my wife and I went on a cruise to the Galapagos. There was a sea food buffet you wouldn&#39;t believe. There were clams, and mussels, and oysters, and cracked crab, and snow crab, and king crab. It&#39;s a pity I&#39;m allergic to shellfish.</p><blockquote><p>（说得很慢）然后我和妻子去了加拉帕戈斯。有一个海鲜自助餐，你简直不敢相信。有蛤蜊、贻贝、牡蛎、裂蟹、雪蟹和帝王蟹。很遗憾我对贝类过敏。</p></blockquote><p><strong>Ross Geller:</strong> (very bored, he tries to avoid the conversation speaking to Charlie) So, where did you get your undergraduate degree?</p><blockquote><p>（非常无聊，他试图避开与查理的对话）那么，你是从哪里获得本科学位的？</p></blockquote><p><strong>Professor Spafford:</strong> And that&#39;s not all I&#39;m allergic to.</p><blockquote><p>这并不是我过敏的全部。</p></blockquote><p><strong>Ross Geller:</strong> (to Charlie) Oh, it&#39;s not over!</p><blockquote><p>（对查理）哦，还没结束！</p></blockquote><p><strong>Professor Spafford:</strong> I&#39;m also allergic to peanuts, and cashews, and almonds, and filberts...</p><blockquote><p>我也对花生、腰果、杏仁和榛子过敏。。。</p></blockquote><p><strong>Ross Geller:</strong> So basically all nuts?</p><blockquote><p>那么基本上都是坚果？</p></blockquote><p><strong>Professor Spafford:</strong> Interestingly... no.</p><blockquote><p>有趣的是。。。不</p></blockquote><p><strong>Charlie:</strong> Kinda playing fast and loose with the word &quot;interesting&quot;.</p><blockquote><p>有点玩弄“有趣”这个词。</p></blockquote><p><strong>Professor Spafford:</strong> If you&#39;ll excuse me I&#39;m going to use the restroom. (he goes away)</p><blockquote><p>请原谅，我要去洗手间。（他走开了）</p></blockquote><p><strong>Charlie:</strong> Oh my God!!</p><blockquote><p>哦，我的天哪！！</p></blockquote><p><strong>Ross Geller:</strong> I&#39;ve lost the will to live.</p><blockquote><p>我已经失去了生存的意志。</p></blockquote><p><strong>Charlie:</strong> Let&#39;s ditch him!</p><blockquote><p>我们甩掉他吧！</p></blockquote><p><strong>Ross Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Charlie:</strong> Come on, he&#39;s still in the bathroom! I&#39;m begging you!</p><blockquote><p>拜托，他还在浴室里！我求你了！</p></blockquote><p><strong>Ross Geller:</strong> Oh... ok, fine. But... ehm... I just have one question for you, ehm... (aping Professor Spafford) When we exit should we walk, or run, or prance, or stroll...</p><blockquote><p>哦。。。好的。但是嗯。。。我只想问你一个问题，嗯。。。（模仿斯帕福德教授）当我们离开时，我们应该走路、跑步、跳跃还是散步。。。</p></blockquote><p><strong>Charlie:</strong> Stop it, stop it! He talks slow but he might pee fast! Ok, let&#39;s go!! (they run outside)</p><blockquote><p>住手，住手！他说话慢，但可能尿得快！好的，我们走吧！！（他们跑到外面）</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s apartment</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒的公寓</em></p></blockquote><p><strong>Ross Geller:</strong> (entering with Charlie) Oh, hey you guys! This is Charlie! Charlie, this is Phoebe and my sister, Monica.</p><blockquote><p>（和查理一起进来）哦，嘿，你们！这是查理！查理，这是菲比和我妹妹莫妮卡。</p></blockquote><p><strong>Phoebe Buffay:</strong> Hi!</p><blockquote><p>嗨！</p></blockquote><p><strong>Ross Geller:</strong> Yeah, Charlie is gonna be joining my department.</p><blockquote><p>是的，查理将加入我的部门。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, you&#39;re a paleonthologist, too! (pause) Oh, ok, now, what do you think of Ranion&#39;s new theory of species&#39; variegation in segmented arthopods?</p><blockquote><p>哦，你也是古生物学家！（停顿）哦，好吧，现在，你怎么看待拉尼翁关于分段类蹄类动物物种多样性的新理论？</p></blockquote><p><strong>Charlie:</strong> Well, I think he&#39;s a little out there, but he does have some interesting ideas...</p><blockquote><p>嗯，我觉得他有点出类拔萃，但他确实有一些有趣的想法。。。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ah, ah.</p><blockquote><p>啊，啊。</p></blockquote><p><strong>Charlie:</strong> (her mobile phone rings) Oh, I&#39;m sorry. I&#39;ll take this. Excuse me. (she cuts herself off for a moment)</p><blockquote><p>（她的手机响了）哦，对不起。我要这个。打扰一下（她停了一会儿）</p></blockquote><p><strong>Ross Geller:</strong> (to Phoebe) Ranion&#39;s theory of species variegation?</p><blockquote><p>（对菲比）拉尼昂的物种杂色理论？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, I saw the article on your coffee table and I memorized the title to freak you out!</p><blockquote><p>是啊，我在你的咖啡桌上看到了那篇文章，我还记得那篇文章的标题，想吓唬你！</p></blockquote><p><strong>Monica Geller:</strong> (to Ross) So, did you two have fun?</p><blockquote><p>（对罗斯）你们俩玩得开心吗？</p></blockquote><p><strong>Ross Geller:</strong> Oh my God, she&#39;s great! I mean, we-we have so much in common and she&#39;s just cool, and funny...</p><blockquote><p>哦，天哪，她太棒了！我是说，我们有很多共同点，她很酷，很有趣。。。</p></blockquote><p><strong>Monica Geller:</strong> And I don&#39;t know if you&#39;ve noticed but she&#39;s a (aloud) HOTTY!! (Charlie looks at her) HI!</p><blockquote><p>我不知道你是否注意到了，但她（大声地）很性感！！（查理看着她）嗨！</p></blockquote><p><strong>Rachel Green:</strong> (she enters wearing a bath-robe) Hey... Hi you guys! Listen, you know what? I&#39;m not feeling really well. I think I can&#39;t get out for the play.</p><blockquote><p>（她穿着浴袍进来）嘿。。。大家好！听着，你知道吗？我感觉不太舒服。我想我不能出去看戏了。</p></blockquote><p><strong>Ross Geller:</strong> Really? Wh-what&#39;s wrong?</p><blockquote><p>真的吗？怎么了？</p></blockquote><p><strong>Rachel Green:</strong> I don&#39;t know! I think it&#39;s kind of serious! Oh, you know... I was watching this thing on TV this morning about... Newcastle disease... and I think I might have it!!</p><blockquote><p>我不知道！我觉得有点严重！哦，你知道。。。今天早上我在电视上看这件关于。。。新城疫。。。我想我可能会得到它！！</p></blockquote><p><strong>Charlie:</strong> Oh, Newcastle disease is a secretion borne virus that only affects chickens and... other poultry.</p><blockquote><p>哦，新城疫是一种分泌物传播的病毒，只影响鸡和。。。其他家禽。</p></blockquote><p><strong>Rachel Green:</strong> ... Ok, who is this?</p><blockquote><p>。。。好的，这是谁？</p></blockquote><p><strong>Ross Geller:</strong> I&#39;m sorry, Rachel, this is Charlie Wealer, she&#39;s a collegue.</p><blockquote><p>对不起，瑞秋，这是查理·韦勒，她是个大学生。</p></blockquote><p><strong>Rachel Green:</strong> Oh, hi! I would check your hand but... I&#39;m sure you don&#39;t want to get my chicken disease!</p><blockquote><p>哦，嗨！我会检查你的手但是。。。我肯定你不想让我得鸡病！</p></blockquote><p><strong>Monica Geller:</strong> Hey, Rachel, Can-can I see you for a sec?</p><blockquote><p>嘿，瑞秋，我能见你一会儿吗？</p></blockquote><p><strong>Rachel Green:</strong> Sure! (Monica takes her apart) Oh...</p><blockquote><p>当然！（莫妮卡把她分开）哦。。。</p></blockquote><p><strong>Monica Geller:</strong> You&#39;re not sick!</p><blockquote><p>你没病！</p></blockquote><p><strong>Rachel Green:</strong> What? Yes, I am!</p><blockquote><p>什么？是的，我是！</p></blockquote><p><strong>Monica Geller:</strong> Ok, then, why are you... (she opens her robe revealing a nice black dress) all dressed up??</p><blockquote><p>好吧，那你为什么。。。（她打开长袍，露出一件漂亮的黑色连衣裙）都穿好了吗？？</p></blockquote><p><strong>Rachel Green:</strong> When you&#39;re sick, you do whatever you can to make yourself feel better! (she closes her robe)</p><blockquote><p>当你生病的时候，你会尽你所能让自己感觉好一点！（她合上长袍）</p></blockquote><p><strong>Monica Geller:</strong> You just wanna stay home so you can make a move on Joey!</p><blockquote><p>你只想呆在家里，这样你就可以对乔伊采取行动了！</p></blockquote><p><strong>Rachel Green:</strong> Oh, no, no! I heard you before, that is so not what this is!</p><blockquote><p>哦，不，不！我以前听过你说的，这不是真的！</p></blockquote><p><strong>Monica Geller:</strong> Ok, what is this?</p><blockquote><p>好的，这是什么？</p></blockquote><p><strong>Rachel Green:</strong> Ok! (whispering) Joey is having a secret Days Of Our Lives party up on the roof and he sent you guys to the play to get rid of you!</p><blockquote><p>好的！（耳语）乔伊在屋顶上举办了一个秘密的“我们生活的日子”聚会，他派你们去看戏是为了摆脱你们！</p></blockquote><p><strong>Monica Geller:</strong> (aloud) WHAT?</p><blockquote><p>（大声）什么？</p></blockquote><p><strong>Ross Geller:</strong> (looking at them) Wh-what&#39;s going on?</p><blockquote><p>（看着他们）怎么回事？</p></blockquote><p><strong>Monica Geller:</strong> Joey is having a secret Days Of Our Lives party up on the roof!</p><blockquote><p>乔伊在屋顶上举行了一个我们生活中的秘密聚会！</p></blockquote><p><strong>Rachel Green:</strong> And he didn&#39;t want you guys to know about it but I came over here to tell you!!</p><blockquote><p>他不想让你们知道这件事，但我是来告诉你们的！！</p></blockquote><p><strong>Charlie:</strong> I thought you came to say you were sick.</p><blockquote><p>我以为你是来说你病了。</p></blockquote><p><strong>Rachel Green:</strong> Ok professor or detective?</p><blockquote><p>好吧，教授还是侦探？</p></blockquote><p><strong>Phoebe Buffay:</strong> Joey&#39;s having a party and he wasn&#39;t gonna invite us?</p><blockquote><p>乔伊在开派对，他不邀请我们？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, and he does it every year! That&#39;s why he&#39;s sending you to that play! That&#39;s why he sent us to that medieval restaurant and to that button factory!</p><blockquote><p>是啊，他每年都这么做！这就是为什么他要派你去看那出戏！这就是为什么他把我们送到那个中世纪的餐馆和那个纽扣厂！</p></blockquote><p><strong>Phoebe Buffay:</strong> And that horrible museum tour!</p><blockquote><p>还有那可怕的博物馆之旅！</p></blockquote><p><strong>Ross Geller:</strong> No, I arranged that...</p><blockquote><p>不，是我安排的。。。</p></blockquote><p><em>(Joey enters, wearing a bathrobe)</em></p><blockquote><p><em>（乔伊穿着浴衣进来）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (sounds tired) Hey you guys, I&#39;m turning in. Have fun.</p><blockquote><p>（听起来很累）嘿，你们这些家伙，我要上厕所了。玩得高兴</p></blockquote><p><strong>Phoebe Buffay:</strong> We know about your party Joey.</p><blockquote><p>我们知道你的派对，乔伊。</p></blockquote><p><strong>Joey Tribbiani:</strong> What party?</p><blockquote><p>什么派对？</p></blockquote><p><strong>Monica Geller:</strong> The game&#39;s over! Take off your robe!</p><blockquote><p>游戏结束了！脱下你的长袍！</p></blockquote><p><strong>Joey Tribbiani:</strong> (looks perplexed and opens up his robe) Ok... I mean...</p><blockquote><p>（看起来很困惑，打开了他的长袍）好的。。。我是说。。。</p></blockquote><p><strong>Everyone:</strong> No!! Cover it up!!</p><blockquote><p>不！！掩盖它！！</p></blockquote><p><strong>Joey Tribbiani:</strong> (to Charlie after covering himself up again) Nice to meet ya! (Charlie waves hesitantly and Joey leaves)</p><blockquote><p>（再次掩饰后对查理说）很高兴认识你！（查理犹豫地挥手，乔伊离开）</p></blockquote><hr><p>🎬 <em>The Roof</em></p><blockquote><p>🎬 <em>屋顶</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (To some people) Hey! Hey alright! Hey, glad you could make it (Shakes a man&#39;s hand) Thanks for coming.</p><blockquote><p>（对一些人）嘿！嘿，好吧！嘿，很高兴你能来（和一个男人握手）谢谢你的到来。</p></blockquote><p><strong>Monica Geller:</strong> Oh my God! Kyle Lowder!</p><blockquote><p>哦，我的天啊！凯尔·洛德！</p></blockquote><p><strong>Kyle Lowder:</strong> (to Monica) Hi. (walks on)</p><blockquote><p>（对莫妮卡）嗨。（继续走）</p></blockquote><p><strong>Monica Geller:</strong> (Yells after him) I love you!</p><blockquote><p>（跟在他后面喊）我爱你！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, that&#39;s why I didn&#39;t invite you. you have to calm down, alright... go, go get yourself a drink or something...</p><blockquote><p>嘿，这就是为什么我没有邀请你。你必须冷静下来，好吗。。。去，去喝点什么吧。。。</p></blockquote><p><strong>Monica Geller:</strong> Oh yeah that&#39;s what you want - my inhibitions lowered.</p><blockquote><p>哦，是的，那正是你想要的——我的抑制降低了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Monica Geller:</strong> (Excited) Oh my God, can you believe we are surrounded by all this? I can barely control myself.</p><blockquote><p>（激动）哦，我的天，你能相信我们被这一切包围了吗？我几乎无法控制自己。</p></blockquote><p><strong>Phoebe Buffay:</strong> Monica, you might want to remember that you are married. Where is Chandler anyway? (Looks around)</p><blockquote><p>莫妮卡，你可能想记住你已经结婚了。钱德勒到底在哪里？（环顾四周）</p></blockquote><p><strong>Monica Geller:</strong> (Shocked) Oh my God! Chandler!</p><blockquote><p>（震惊）哦，我的天啊！经销商</p></blockquote><hr><p>🎬 <em>The theater. Chandler is sitting in the otherwise empty front row, looking around nervously</em></p><blockquote><p>🎬 <em>剧院。钱德勒坐在空荡荡的前排，紧张地环顾四周</em></p></blockquote><p><strong>Chandler Bing:</strong> Where the hell is everybody?</p><blockquote><p>大家都去哪了？</p></blockquote><p><em>(The lights dim and Chandler tries to get away but as the bitter lady comes on stage and starts yelling he promptly changes his mind and sits down)</em></p><blockquote><p><em>（灯光昏暗，钱德勒试图逃走，但当这位苦涩的女士走上舞台并开始大喊大叫时，他立刻改变了主意，坐了下来）</em></p></blockquote><p><strong>Bitter lady:</strong> (yelling) Why don&#39;t you like me?! Chapter One: My first period.</p><blockquote><p>（大叫）你为什么不喜欢我？！第一章：我的第一节课。</p></blockquote><hr><p>🎬 <em>The Roof, Rachel is talking to a guy who hands her a tissue with something written on it</em></p><blockquote><p>🎬 <em>屋顶上，瑞秋正在和一个递给她一张写有东西的纸巾的家伙说话</em></p></blockquote><p><strong>Monica Geller:</strong> (to Rachel) Hey! Joey said no autographs! But if she&#39;s gettting one, then I want one too: To Monica. And none of this &quot;best wishes&quot; crap. I want &quot;love&quot;.</p><blockquote><p>（对瑞秋）嘿！乔伊说没有签名！但是如果她得到一个，那么我也想要一个：给莫妮卡。这些“最好的祝愿”都不是废话。我想要“爱”。</p></blockquote><p><strong>Rachel Green:</strong> Ok actually Mon, Matthew was just giving me his phone number.</p><blockquote><p>好的，事实上，妈妈，马修刚刚给了我他的电话号码。</p></blockquote><p><strong>Monica Geller:</strong> Oh man! If I had known I was coming to this party I never would have gotten married!</p><blockquote><p>哦，老兄！如果我知道我要来参加这个聚会，我就不会结婚了！</p></blockquote><p><strong>Matthew Ashford:</strong> It was nice to meet you Rachel.</p><blockquote><p>很高兴认识你，瑞秋。</p></blockquote><p><strong>Rachel Green:</strong> Nice to meet you.</p><blockquote><p>很高兴认识你。</p></blockquote><p><strong>Matthew Ashford:</strong> Call me.</p><blockquote><p>打电话给我。</p></blockquote><p><strong>Rachel Green:</strong> Ok</p><blockquote><p>好的</p></blockquote><p><em>(Matthew leaves)</em></p><blockquote><p><em>（马修离开）</em></p></blockquote><p><strong>Monica Geller:</strong> (yelling after him) We will!!</p><blockquote><p>（朝他喊）我们会的！！</p></blockquote><p><strong>Monica Geller:</strong> (to Rachel) Look at you with all the guys!</p><blockquote><p>（对瑞秋）看看你和所有的男人！</p></blockquote><p><strong>Rachel Green:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Monica Geller:</strong> I guess you have forgotten all about Joey?</p><blockquote><p>我想你已经把乔伊忘得一干二净了吧？</p></blockquote><p><strong>Rachel Green:</strong> Yeah, well, I guess I have forgotten about Joey and clearly you&#39;ve forgotten about Chandler!</p><blockquote><p>是啊，我想我忘了乔伊，很明显你也忘了钱德勒！</p></blockquote><p><strong>Monica Geller:</strong> Please... Chandler is the love of my life... (At which point a man in leather pants walks by)... oooh leather pants! Have Mercy! (Follows the man in the leather)</p><blockquote><p>请。。。钱德勒是我一生的挚爱。。。（这时一个穿着皮裤的男人走过）。。。哦，皮裤！发发慈悲吧！（跟着穿皮衣的人）</p></blockquote><p><em>(cut to Ross and Charlie)</em></p><blockquote><p><em>（转到罗斯和查理）</em></p></blockquote><p><strong>Ross Geller:</strong> (to Charlie) So, eh... it&#39;s probably gonna be hard for you to leave Boston, huh?</p><blockquote><p>（对查理）那么，呃。。。离开波士顿对你来说可能很难吧？</p></blockquote><p><strong>Charlie:</strong> Actually, I&#39;m kinda happy to be leaving... I just broke up with someeone.</p><blockquote><p>事实上，我很高兴能离开。。。我刚和某个人分手。</p></blockquote><p><strong>Ross Geller:</strong> Ooh... so sad... Still, it can&#39;t be easy for you to leave Harvard? Especially after working alongside a Nobel Prize winner like Albert Wintermeyer?</p><blockquote><p>哦。。。如此悲伤。。。不过，你离开哈佛并不容易吧？尤其是在和阿尔伯特·温特梅尔这样的诺贝尔奖获得者一起工作之后？</p></blockquote><p><strong>Charlie:</strong> Actually, Alby is the guy I broke up with.</p><blockquote><p>事实上，阿尔比就是和我分手的那个人。</p></blockquote><p><strong>Ross Geller:</strong> You... you dated Albert Wintermeyer?</p><blockquote><p>你。。。你和艾伯特·温特梅尔约会了？</p></blockquote><p><strong>Charlie:</strong> Yeah...</p><blockquote><p>是的。。。</p></blockquote><p><strong>Ross Geller:</strong> ... And you called him Alby!? (laughs) I mean that&#39;s like... like calling Albert Einstein... er... Alby...</p><blockquote><p>。。。你叫他阿尔比！？（笑）我的意思是那就像。。。比如叫阿尔伯特·爱因斯坦。。。呃。。。阿尔比。。。</p></blockquote><p><strong>Charlie:</strong> Yeah, well, he is a brilliant man.</p><blockquote><p>是的，嗯，他是个聪明人。</p></blockquote><p><strong>Ross Geller:</strong> Eh, you think? I mean, you went out with a guy who improved the accuracy of radiocarbon dating by a factor of 10!</p><blockquote><p>嗯，你觉得呢？我是说，你和一个家伙约会，他把放射性碳年代测定的准确度提高了10倍！</p></blockquote><p><strong>Charlie:</strong> Yes! And while that is everything one looks for in a boyfriend, he had a lot of issues...</p><blockquote><p>是的！虽然这是一个人在男朋友身上寻找的一切，但他有很多问题。。。</p></blockquote><p><strong>Ross Geller:</strong> (very interested) Oh! like what?! (Charlie looks at him confused, but smiling) Oh I&#39;m sorry, I don&#39;t mean to pry... it&#39;s just that this must be what regular people experience when they watch &quot;Access Hollywood&quot;.</p><blockquote><p>（非常感兴趣）哦！像什么？！（查理困惑地看着他，但微笑着）哦，对不起，我不是想打听。。。只是这一定是普通人在看《进入好莱坞》时的体验。</p></blockquote><p><strong>Charlie:</strong> Ok, you want the dirt? Alby was seriously insecure. I mean, he was really intimidated by the guy I dated before him.</p><blockquote><p>好吧，你想要脏东西吗？阿尔比非常不安全。我的意思是，他真的被我在他之前约会的那个家伙吓坏了。</p></blockquote><p><strong>Ross Geller:</strong> Who is intimidating to a guy who won the Nobel Prize?</p><blockquote><p>谁在恐吓一个获得诺贝尔奖的人？</p></blockquote><p><strong>Charlie:</strong> A guy who won two.</p><blockquote><p>一个赢了两次的家伙。</p></blockquote><p><strong>Ross Geller:</strong> (a little suprised) Two? Wha...? Don&#39;t tell me you dated Benjamin Hobart</p><blockquote><p>（有点惊讶）两个？什么。。。？别告诉我你和本杰明·霍巴特约会过</p></blockquote><p><strong>Charlie:</strong> Yeah... for three years.</p><blockquote><p>是的。。。三年了。</p></blockquote><p><strong>Ross Geller:</strong> Oh my God! Have you ever been in a relationship with someone who hasn&#39;t won the Nobel Prize?</p><blockquote><p>哦，我的天啊！你有没有和一个没有获得诺贝尔奖的人发生过关系？</p></blockquote><p><strong>Charlie:</strong> (smiling and thinks for a moment)... no... bu but there was my first boyfriend Billy.</p><blockquote><p>（微笑着想了一会儿）。。。不但是有我的第一个男朋友比利。</p></blockquote><p><strong>Ross Geller:</strong> Oh yeah? no, no Nobel Prizes for him?</p><blockquote><p>哦，是吗？不，他没有诺贝尔奖？</p></blockquote><p><strong>Charlie:</strong> No, but he did just win the McArthur genius grant.</p><blockquote><p>没有，但他刚刚赢得了麦克阿瑟天才奖。</p></blockquote><p><strong>Ross Geller:</strong> Huh... huh... what a loser! Some more wine? (takes the half-full glasses and goes to the counter)</p><blockquote><p>嗯。。。呵呵。。。真是个失败者！再来点酒吗？（拿着半满的杯子走向柜台）</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey Ross!</p><blockquote><p>嘿，罗斯！</p></blockquote><p><strong>Rache:</strong> How is it going with Charlie?</p><blockquote><p>查理怎么样了？</p></blockquote><p><strong>Ross Geller:</strong> (sarcastically) Oh Great! After I finish my wine I&#39;m going to blow my... eh. average-sized brains out.</p><blockquote><p>（讽刺地）哦，太好了！等我喝完我的酒我要吹我的。。。嗯。平均大小的大脑。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, What&#39;s the matter?</p><blockquote><p>哦，怎么了？</p></blockquote><p><strong>Ross Geller:</strong> She... she only dates geniuses and Nobel Prize winners. Oh my God, at the chinese restaurant earlier today, I put chopsticks in my mouth and pretented to be a woolly mammoth.</p><blockquote><p>她。。。她只和天才和诺贝尔奖得主约会。天哪，今天早些时候在中餐馆，我把筷子放进嘴里，假装是一头长毛象。</p></blockquote><p><strong>Rachel Green:</strong> I always loved that!!</p><blockquote><p>我一直很喜欢这个！！</p></blockquote><p><strong>Ross Geller:</strong> Of course you would, your brains are smaller than mine!! (Rachel nods) Man, I can&#39;t compete with the guys she goes out with, they are so out of my league! oh my God!</p><blockquote><p>你当然会，你的大脑比我的小！！（瑞秋点点头）老兄，我不能和她约会的那些家伙竞争，他们太不适合我了！哦，我的上帝！</p></blockquote><p><strong>Phoebe Buffay:</strong> Worse?</p><blockquote><p>更糟？</p></blockquote><p><strong>Ross Geller:</strong> Oh much, much worse. I did my impression of Joan Rivers as one of the earliest amphibians... (gestures with his hands and says in an impression voice?) &quot;Can we walk&quot;? (Phoebe starts laughing) Oh, you... you like that?</p><blockquote><p>哦，更糟，更糟。我对琼·里弗斯的印象是最早的两栖动物之一。。。（用他的手做手势，用印象中的声音说？“我们能走路吗？”？（菲比笑了起来）哦，你。。。你喜欢吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> (still laughing) No. (points to Rachel who stuck two straws in her mouth to look like a mammoth&#39;s tusks)</p><blockquote><p>（还在笑）没有。（指着瑞秋，她把两根吸管塞进嘴里，看起来像猛犸象的獠牙）</p></blockquote><p><strong>Ross Geller:</strong> What? (turns around to look at Rachel)</p><blockquote><p>什么？（转身看着瑞秋）</p></blockquote><p><strong>Rachel Green:</strong> Come on! I think this is funny! (Ross leaves)</p><blockquote><p>来吧！我觉得这很有趣！（罗斯离开）</p></blockquote><hr><p>🎬 <em>Chandler in the theater</em></p><blockquote><p>🎬 <em>钱德勒在剧院</em></p></blockquote><p><strong>Bitter lady:</strong> Well, I bet you are all thinkin&#39; &quot;Now would be a really great time for an intermission&quot;, huh?</p><blockquote><p>嗯，我打赌你们都在想“现在是休息的好时机”，嗯？</p></blockquote><p><strong>Chandler Bing:</strong> (To himself) oh yes, God yes!!</p><blockquote><p>（对自己说）哦，是的，上帝是的！！</p></blockquote><p><strong>Bitter lady:</strong> (now yelling) Well, you&#39;re not gonna get one! Because in life there are no intermissions, people. Chapter 7: Divorce is a 4 letter word. (Now standing right in front of Chandler and bending down almost to his level as if speaking to him, yelling even louder) How could he leave me?!?!</p><blockquote><p>（现在大叫）好吧，你不会得到一个！因为在生活中没有休止符，人们。第七章：离婚是一个四个字母的单词。（现在站在钱德勒面前，弯下腰，几乎和他一样，好像在跟他说话，喊得更大声）他怎么能离开我？！？！</p></blockquote><p><strong>Chandler Bing:</strong> I... I don&#39;t know... you seem lovely.</p><blockquote><p>我。。。我不知道。。。你看起来很可爱。</p></blockquote><hr><p>🎬 <em>The roof, Joey is walking towards Ross with a guy</em></p><blockquote><p>🎬 <em>屋顶，乔伊正和一个男人朝罗斯走去</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey Ross, this is one of my co-stars, Dirk. (To Dirk) Dirk, this is my good friend Ross. (Ross and Dirk shake hands)</p><blockquote><p>嘿，罗斯，这是我的一个搭档，德克。（对德克）德克，这是我的好朋友罗斯。（罗斯和德克握手）</p></blockquote><p><strong>Ross Geller:</strong> Nice to meet you.</p><blockquote><p>很高兴认识你。</p></blockquote><p><strong>Dirk:</strong> Hey! So what show are you on?</p><blockquote><p>嘿！你在演什么节目？</p></blockquote><p><strong>Ross Geller:</strong> Oh, I&#39;m no actor, I&#39;m a professor of palaeontology.</p><blockquote><p>哦，我不是演员，我是古生物学教授。</p></blockquote><p><em>(Dirk is confused)</em></p><blockquote><p><em>（德克感到困惑）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s a science.</p><blockquote><p>这是一门科学。</p></blockquote><p><strong>Dirk:</strong> Oh! Hey well listen, I play a scientist on &quot;Days&quot;. And my character has just won the Nobel prize.</p><blockquote><p>哦！嘿，听着，我在“天”里扮演一个科学家。我的角色刚刚获得诺贝尔奖。</p></blockquote><p><em>(Ross looks annoyed hearing that even Dirk&#39;s character won a Nobel prize)</em></p><blockquote><p><em>（罗斯听到德克的角色也获得了诺贝尔奖，看起来很恼火）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey Ross, listen, Dirk was wondering about the woman that you brought and if you guys were together, or...</p><blockquote><p>嘿，罗斯，听着，德克想知道你带来的那个女人，你们是不是在一起，或者。。。</p></blockquote><p><strong>Ross Geller:</strong> Oh, well no, but I mean, she only goes out with really, really smart guys.</p><blockquote><p>哦，不，但我是说，她只和非常非常聪明的男人约会。</p></blockquote><p><strong>Dirk:</strong> Hey, I got a 690 on my SATs.</p><blockquote><p>嘿，我的SAT考试得了690分。</p></blockquote><p><strong>Ross Geller:</strong> I&#39;d lead with that.</p><blockquote><p>那我就先说吧。</p></blockquote><p><em>(Cut to Monica holding up her shirt, revealing her bra. An actor stands beside her, holding a pen in his hand.)</em></p><blockquote><p><em>（镜头切换到莫妮卡举起衬衫，露出胸罩。一名演员站在她身边，手里拿着一支笔。）</em></p></blockquote><p><strong>Monica Geller:</strong> That&#39;s it, just sign right on the bra (the actor does so).</p><blockquote><p>就这样，在胸罩上签个字就行了（演员就是这么做的）。</p></blockquote><p><strong>Joey Tribbiani:</strong> Monica!</p><blockquote><p>莫妮卡！</p></blockquote><p><strong>Monica Geller:</strong> Don&#39;t worry Joe, I won&#39;t come next year!</p><blockquote><p>别担心，乔，我明年不会来了！</p></blockquote><p><em>(Joey, resigned, walks to Rachel&#39;s table)</em></p><blockquote><p><em>（乔伊辞职，走向瑞秋的桌子）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (To Rachel) What have you got there?</p><blockquote><p>（对瑞秋）你有什么？</p></blockquote><p><strong>Ross Geller:</strong> Just some boys gave me their phone numbers.</p><blockquote><p>只是一些男孩给了我他们的电话号码。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ah, let me see! (she hands him a pile of tissues) Damn, that&#39;s a lot of guys! Are you a little slutty?</p><blockquote><p>啊，让我想想！（她递给他一堆纸巾）该死，那是很多人！你有点放荡吗？</p></blockquote><p><strong>Rachel Green:</strong> (drunken voice) I think I am.</p><blockquote><p>（醉声）我想是的。</p></blockquote><p><strong>Joey Tribbiani:</strong> (browsing the tissues) Let me see if I approve any of these clowns. This guy wears a rug (discards one). This guy&#39;s Canadian (discards another). And this guy is in a cult, ok, and it costs you 5,000$ to get to level three and I don&#39;t feel any different.</p><blockquote><p>（浏览纸巾）让我看看我是否认可这些小丑中的任何一个。这家伙戴着一块地毯（扔掉一块）。这家伙是加拿大人（抛弃了另一个）。这家伙是个邪教，好吧，你要花5000美元才能达到三级，我觉得没什么不同。</p></blockquote><p><em>(Rachel is puzzled)</em></p><blockquote><p><em>（瑞秋感到困惑）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (discarding all the remaining tissues one by one) Pass, pass, oh, pass, double-pass, pass...</p><blockquote><p>（一个接一个地扔掉所有剩下的纸巾）传球，传球，哦，传球，双传球，传球。。。</p></blockquote><p><strong>Rachel Green:</strong> (picking up the tissues) Why, why, what&#39;s wrong with these guys?</p><blockquote><p>（拿起纸巾）为什么，为什么，这些家伙怎么了？</p></blockquote><p><strong>Joey Tribbiani:</strong> Nothing major, it&#39;s just that, you know, they&#39;re not really good enough for you, and you deserve the best.</p><blockquote><p>没什么大不了的，只是，你知道，它们对你来说不够好，你应该得到最好的。</p></blockquote><p><strong>Rachel Green:</strong> Joey, you&#39;re so sweet.</p><blockquote><p>乔伊，你真可爱。</p></blockquote><p><strong>Joey Tribbiani:</strong> That&#39;s true. But you know what, it doesn&#39;t matter because I already know who you&#39;re gonna go home with tonight.</p><blockquote><p>没错。但你知道吗，没关系，因为我已经知道你今晚要和谁一起回家。</p></blockquote><p><strong>Rachel Green:</strong> Who (looks around)?</p><blockquote><p>谁（环顾四周）？</p></blockquote><p><em>(Joey motions for Rachel to lean in. She does so.)</em></p><blockquote><p><em>（乔伊示意瑞秋靠进去，她照做了。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Me.</p><blockquote><p>我。</p></blockquote><p><strong>Rachel Green:</strong> (surprised) What? (with a nervous smile) Really?</p><blockquote><p>（惊讶）什么？（带着紧张的微笑）真的吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yes, &#39;cause we live together, that&#39;s a joke!</p><blockquote><p>是的，因为我们住在一起，那是个玩笑！</p></blockquote><p><strong>Rachel Green:</strong> Oh! Screw it, I didn&#39;t get it! (they high-five)</p><blockquote><p>哦！去他妈的，我没弄明白！（他们击掌）</p></blockquote><p><strong>Joey Tribbiani:</strong> Gotcha.</p><blockquote><p>明白了。</p></blockquote><p><strong>Rachel Green:</strong> Oh, Very funny... Joey.</p><blockquote><p>哦，很有趣。。。乔伊。</p></blockquote><p><em>(Joey leaves. Rachel gulps down what&#39;s left of her drink and grimaces.)</em></p><blockquote><p><em>（乔伊离开了。瑞秋大口吞下了她剩下的饮料和鬼脸。）</em></p></blockquote><p><em>(Chandler walks in)</em></p><blockquote><p><em>（钱德勒走进来）</em></p></blockquote><p><strong>Chandler Bing:</strong> (to Monica) So, how did you enjoy the play?</p><blockquote><p>（对莫妮卡）那么，你觉得这出戏怎么样？</p></blockquote><p><strong>Monica Geller:</strong> Oh my god, honey, I&#39;m so so so so so sorry.</p><blockquote><p>哦，我的天，亲爱的，我很抱歉。</p></blockquote><p><strong>Chandler Bing:</strong> Well you should be. You missed the most powerful three hours in the history of the theater.</p><blockquote><p>你应该是。你错过了剧院历史上最精彩的三个小时。</p></blockquote><p><strong>Monica Geller:</strong> You really liked it?</p><blockquote><p>你真的喜欢吗？</p></blockquote><p><strong>Chandler Bing:</strong> Oh yeah! I mean at first I hated it, but why wouldn&#39;t I, because as a man I&#39;ve been trained (bitter woman&#39;s tone) not to listen! (pause) But after chapter 16: &quot;fat, single and ready to mingle&quot;, I was uplifted.</p><blockquote><p>哦，是的！我的意思是一开始我讨厌它，但我为什么不呢，因为作为一个男人，我一直被训练（痛苦女人的语气）不听！（停顿）但在第16章“肥胖、单身、准备好交往”之后，我被提升了。</p></blockquote><p><strong>Monica Geller:</strong> Oh really!</p><blockquote><p>哦，真的！</p></blockquote><p><strong>Chandler Bing:</strong> Oh yeah, I had no idea the amazing journey you go through as a woman! Tell me, tell me about your first period!</p><blockquote><p>哦，是的，我不知道你作为一个女人所经历的奇妙旅程！告诉我，告诉我你的第一次月经！</p></blockquote><p><strong>Monica Geller:</strong> No!</p><blockquote><p>不！</p></blockquote><p><strong>Chandler Bing:</strong> Did somebody sign your bra?</p><blockquote><p>有人在你的胸罩上签名了吗？</p></blockquote><p><strong>Monica Geller:</strong> So I got it when I was 13...</p><blockquote><p>所以我13岁的时候得到的。。。</p></blockquote><hr><p>🎬 <em>At the counter. Ross is sitting there, drinking. Phoebe approaches him.</em></p><blockquote><p>🎬 <em>在柜台。罗斯坐在那里喝酒。菲比走近他。</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Hey Ross! So listen, about you and the dinosaur girl, are you really just gonna let a couple of Nobel prizes scare you off? What is that, come on, a piece of paper?</p><blockquote><p>嘿，罗斯！听着，关于你和恐龙女孩，你真的想让几个诺贝尔奖吓跑你吗？那是什么，拜托，一张纸？</p></blockquote><p><strong>Ross Geller:</strong> It&#39;s actually a 1,000,000$ prize.</p><blockquote><p>实际上是一百万美元的奖金。</p></blockquote><p><strong>Phoebe Buffay:</strong> Go Charlie! But my point is, ok so she dated them but she also broke up with them. Maybe she&#39;s looking to, you know, slum it with some average Joe Phd.</p><blockquote><p>去吧，查理！但我的意思是，好吧，她和他们约会了，但她也和他们分手了。也许她想，你知道，和一些普通的乔博士住在一起。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, maybe. I do have my whole career in front of me. I mean, I can still win a Nobel prize. Although the last two papers I&#39;ve written were widely discredited.</p><blockquote><p>是的，也许吧。我的整个职业生涯都摆在我面前。我的意思是，我仍然可以获得诺贝尔奖。虽然我写的最后两篇论文被广泛质疑。</p></blockquote><p><strong>Phoebe Buffay:</strong> You&#39;re so much more than just brains! You&#39;re sweet, and kind, and funny...</p><blockquote><p>你不仅仅是个头脑！你很可爱，善良，有趣。。。</p></blockquote><p><strong>Ross Geller:</strong> And sexy.</p><blockquote><p>而且性感。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ok well give her a chance to see all of that!</p><blockquote><p>好吧，那就给她一个机会看看这一切吧！</p></blockquote><p><strong>Ross Geller:</strong> Yeah, you&#39;re right, thanks Pheebs, I&#39;m gonna go find her.</p><blockquote><p>是的，你说得对，谢谢菲比，我要去找她。</p></blockquote><p><strong>Phoebe Buffay:</strong> Good for you! And hey, I thought your paper on punctuated equilibrium in the Devonian era was top notch!</p><blockquote><p>太好了！嘿，我还以为你关于泥盆纪时期标点平衡的论文是一流的！</p></blockquote><p><strong>Ross Geller:</strong> Stop going through my stuff (walks away)!</p><blockquote><p>别再看我的东西了（走开）！</p></blockquote><p><em>(Rachel approaches Monica)</em></p><blockquote><p><em>（瑞秋走近莫妮卡）</em></p></blockquote><p><strong>Rachel Green:</strong> (to Monica) Hey!</p><blockquote><p>（对莫妮卡）嘿！</p></blockquote><p><strong>Monica Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Rachel Green:</strong> I just wanted to let you know I&#39;ve changed my mind: I&#39;m gonna do it, I&#39;m gonna kiss Joey.</p><blockquote><p>我要去做，我要吻乔伊。</p></blockquote><p><strong>Monica Geller:</strong> No, you can&#39;t! Friends hooking up is a bad idea.</p><blockquote><p>不，你不能！朋友勾搭是个坏主意。</p></blockquote><p><strong>Rachel Green:</strong> Please, what about you and Chandler?</p><blockquote><p>拜托，你和钱德勒怎么样？</p></blockquote><p><strong>Monica Geller:</strong> That&#39;s different! I was drunk and stupid!</p><blockquote><p>那不一样！我喝醉了，又蠢！</p></blockquote><p><strong>Rachel Green:</strong> Well hello (points to herself)!</p><blockquote><p>你好（指着自己）！</p></blockquote><p><strong>Monica Geller:</strong> What about all the guys that you&#39;ve got the phone numbers from? Why don&#39;t you just kiss one of them?</p><blockquote><p>那些你从他们那里得到电话号码的人呢？你为什么不亲吻其中一个呢？</p></blockquote><p><strong>Rachel Green:</strong> I could, I could but I don&#39;t want to! I want to kiss Joey!</p><blockquote><p>我可以，我可以，但我不想！我想吻乔伊！</p></blockquote><p><strong>Monica Geller:</strong> Alright (shrugs). I think it&#39;s a big mistake but it&#39;s your decision.</p><blockquote><p>好的（耸耸肩）。我认为这是一个很大的错误，但这是你的决定。</p></blockquote><p><strong>Rachel Green:</strong> (pause) I&#39;m gonna do it.</p><blockquote><p>（停顿）我会的。</p></blockquote><p><strong>Monica Geller:</strong> And I can&#39;t stop you.</p><blockquote><p>我不能阻止你。</p></blockquote><p><strong>Rachel Green:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><em>(Rachel goes look for Joey. She sees him and Charlie kissing passionately.)</em></p><blockquote><p><em>（瑞秋去找乔伊。她看到他和查理热吻。）</em></p></blockquote><p><strong>Ross Geller:</strong> (to Rachel) Hey Rach, have you seen Charlie anywhere?</p><blockquote><p>（对瑞秋）嘿，瑞秋，你在哪儿见过查理吗？</p></blockquote><p><em>(Rachel just stands there staring at Joey and Charlie in silence. After a while, Ross turns around and sees them.)</em></p><blockquote><p><em>（瑞秋只是站在那里默默地看着乔伊和查理。过了一会儿，罗斯转过身来，看到了他们。）</em></p></blockquote><p><strong>Ross Geller:</strong> I&#39;m smarter than him!</p><blockquote><p>我比他聪明！</p></blockquote><p>Closing credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>The theater. Monica, Phoebe and Chandler are sitting in the first line</em></p><blockquote><p>🎬 <em>剧院。莫妮卡、菲比和钱德勒坐在第一排</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Hey, thank you so much for these tickets, Chandler.</p><blockquote><p>嘿，非常感谢你给我这些票，钱德勒。</p></blockquote><p><strong>Chandler Bing:</strong> Oh well, this was a really important experience for me, and I wanted to share it with you.</p><blockquote><p>哦，这对我来说是一次非常重要的经历，我想和你分享一下。</p></blockquote><p><strong>Monica Geller:</strong> Oh, you&#39;re so wonderful.</p><blockquote><p>哦，你太棒了。</p></blockquote><p><strong>Bitter woman:</strong> Why don&#39;t you like me! Chapter one: my first period.</p><blockquote><p>你为什么不喜欢我！第一章：我的第一节课。</p></blockquote><p><strong>Chandler Bing:</strong> Can&#39;t believe you guys bought that, enjoy your slow death (runs away).</p><blockquote><p>真不敢相信你们买了那个，享受你们的慢死（逃跑）。</p></blockquote>`,677)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};